from pydantic import BaseModel, Field
from typing import Any, Dict, List, Optional
from datetime import datetime, timezone

class AgentProposal(BaseModel):
    """Normalized action proposal generated by a domain specialist agent."""
    recommended_action: str
    short_reason: str
    urgency: str  # critical | high | moderate | low
    expected_effect: Optional[str] = None
    target_metric: str  # e.g., stability, heart_rate, containment_rate, etc.
    action_type: str = "general"  # escalate | mitigate | rhythm_support | unsafe | monitor | general
    effect_label: str = "unchanged"  # improving | worsening | unchanged

class ReviewReport(BaseModel):
    """Evaluation critique generated by the Reviewer/Critic agent."""
    safety_flags: List[str] = Field(default_factory=list)
    confidence_score: int = Field(..., ge=0, le=100)
    criticism: str
    suggested_modification: Optional[str] = None
    is_approved: bool = True

class ExecutionStep(BaseModel):
    """Metadata detailing a single step's execution within the workflow engine."""
    node_name: str
    status: str  # pending | running | completed | failed
    output_summary: Optional[str] = None
    timestamp: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    duration_ms: Optional[float] = None

class SimulationState(BaseModel):
    """Domain-agnostic simulation snapshot representing state variables & metrics."""
    domain: str  # clinical | disaster | logistics
    scenario_id: str
    status_summary: str
    stability_score: int  # 0 to 100
    risk_level: str  # critical | high | moderate | low
    metrics: Dict[str, Any] = Field(default_factory=dict)
    interventions_done: List[str] = Field(default_factory=list)
    decisions_applied: List[str] = Field(default_factory=list)
    pending_actions: List[str] = Field(default_factory=list)
    latest_change: str
    state_outcome: str = "Unchanged"  # Improved | Worsened | Unchanged
    timeline: List[str] = Field(default_factory=list)

class EventSchema(BaseModel):
    """A timeline event log within the AegisFlow session transcript."""
    id: str
    timestamp: datetime = Field(default_factory=lambda: datetime.now(timezone.utc))
    role: str  # expert_1 | expert_2 | critic | orchestrator | system | human
    display_name: str  # e.g., "Lead Cardiologist", "Emergency Safety Critic", etc.
    event_type: str  # proposal | review | orchestration | state_update | override | system_event
    content: str
    status: str  # proposed | reviewed | override | final
    action_metadata: Optional[AgentProposal] = None
    review_metadata: Optional[ReviewReport] = None
    state_change_summary: Optional[str] = None
    execution_steps: Optional[List[ExecutionStep]] = None

class OverrideRequest(BaseModel):
    """Physician or Commander real-time override request payload."""
    directive: str

class SessionSnapshot(BaseModel):
    """API contract returned to the web dashboard for rendering."""
    session_id: str
    domain: str
    scenario_name: str
    case_data: Dict[str, Any] = Field(default_factory=dict)
    events: List[EventSchema] = Field(default_factory=list)
    active_directive: Optional[str] = None
    safety_flags: List[str] = Field(default_factory=list)
    next_action: str = "Awaiting initial assessment"
    simulation_state: SimulationState
